    : TVirtualTransport(config), transport_(), rBufSize_(0), wBufSize_(DEFAULT_BUFFER_SIZE), rBuf_(),
      wBuf_(new uint8_t[wBufSize_]), bufReclaimThresh_((std::numeric_limits<uint32_t>::max)()) { initPointers(); }

  TFramedTransport(std::shared_ptr<TTransport> transport, std::shared_ptr<TConfiguration> config = nullptr)
    : TVirtualTransport(config), transport_(transport), rBufSize_(0), wBufSize_(DEFAULT_BUFFER_SIZE), rBuf_(),
      wBuf_(new uint8_t[wBufSize_]), bufReclaimThresh_((std::numeric_limits<uint32_t>::max)()),
      maxFrameSize_(configuration_->getMaxFrameSize()) { initPointers(); }

  TFramedTransport(std::shared_ptr<TTransport> transport, uint32_t sz, uint32_t bufReclaimThresh = (std::numeric_limits<uint32_t>::max)(), std::shared_ptr<TConfiguration> config = nullptr)
    : TVirtualTransport(config), transport_(transport), rBufSize_(0), wBufSize_(sz), rBuf_(),
      wBuf_(new uint8_t[wBufSize_]), bufReclaimThresh_(bufReclaimThresh),
      maxFrameSize_(configuration_->getMaxFrameSize()) { initPointers(); }

  void open() override { transport_->open(); }
  bool isOpen() const override { return transport_->isOpen(); }
  bool peek() override { return (rBase_ < rBound_) || transport_->peek(); }
  void close() override { flush(); transport_->close(); }

  uint32_t readSlow(uint8_t* buf, uint32_t len) override;
  void writeSlow(const uint8_t* buf, uint32_t len) override;
  void flush() override;
  uint32_t readEnd() override;
  uint32_t writeEnd() override;
  const uint8_t* borrowSlow(uint8_t* buf, uint32_t* len) override;

  std::shared_ptr<TTransport> getUnderlyingTransport() { return transport_; }
  using TBufferBase::readAll;
  const std::string getOrigin() const override { return transport_->getOrigin(); }
  void setMaxFrameSize(uint32_t maxFrameSize) { maxFrameSize_ = maxFrameSize; }
  uint32_t getMaxFrameSize() { return maxFrameSize_; }

protected:
  virtual bool readFrame();
  void initPointers() {
    setReadBuffer(nullptr, 0);
    setWriteBuffer(wBuf_.get(), wBufSize_);
    int32_t pad = 0;
    this->write(reinterpret_cast<uint8_t*>(&pad), sizeof(pad));
  }

  std::shared_ptr<TTransport> transport_;
  uint32_t rBufSize_;
  uint32_t wBufSize_;
  std::unique_ptr<uint8_t[]> rBuf_;
  std::unique_ptr<uint8_t[]> wBuf_;
  uint32_t bufReclaimThresh_;
  uint32_t maxFrameSize_;
};

