class TMemoryBuffer : public TVirtualTransport<TMemoryBuffer, TBufferBase> {
private:
  void initCommon(uint8_t* buf, uint32_t size, bool owner, uint32_t wPos) {
    maxBufferSize_ = (std::numeric_limits<uint32_t>::max)();
    if (buf == nullptr && size != 0) {
      assert(owner);
      buf = static_cast<uint8_t*>(std::malloc(size));
      if (buf == nullptr) { throw std::bad_alloc(); }
    }
    buffer_ = buf;
    bufferSize_ = size;
    rBase_ = buffer_;
    rBound_ = buffer_ + wPos;
    wBase_ = buffer_ + wPos;
    wBound_ = buffer_ + bufferSize_;
    owner_ = owner;
  }
public:
  static const uint32_t defaultSize = 1024;
  enum MemoryPolicy { OBSERVE = 1, COPY = 2, TAKE_OWNERSHIP = 3 }; 

  TMemoryBuffer(std::shared_ptr<TConfiguration> config = nullptr) : TVirtualTransport(config) { initCommon(nullptr, defaultSize, true, 0); }
  TMemoryBuffer(uint32_t sz, std::shared_ptr<TConfiguration> config = nullptr) : TVirtualTransport(config) { initCommon(nullptr, sz, true, 0); }
  TMemoryBuffer(uint8_t* buf, uint32_t sz, MemoryPolicy policy = OBSERVE, std::shared_ptr<TConfiguration> config = nullptr)
    : TVirtualTransport(config) {
    if (buf == nullptr && sz != 0) {
      throw TTransportException(TTransportException::BAD_ARGS,
                                "TMemoryBuffer given null buffer with non-zero size.");
    }
    switch (policy) {
    case OBSERVE:
    case TAKE_OWNERSHIP:
      initCommon(buf, sz, policy == TAKE_OWNERSHIP, sz);
      break;
    case COPY:
      initCommon(nullptr, sz, true, 0);
      this->write(buf, sz);
      break;
    default:
      throw TTransportException(TTransportException::BAD_ARGS,
                                "Invalid MemoryPolicy for TMemoryBuffer");
    }
  }
  ~TMemoryBuffer() override { if (owner_) { std::free(buffer_); } }
  bool isOpen() const override { return true; }
  bool peek() override { return (rBase_ < wBase_); }
  void open() override {}
  void close() override {}
  void getBuffer(uint8_t** bufPtr, uint32_t* sz) { *bufPtr = rBase_; *sz = static_cast<uint32_t>(wBase_ - rBase_); }
  std::string getBufferAsString() { if (buffer_ == nullptr) { return ""; } uint8_t* buf; uint32_t sz; getBuffer(&buf, &sz); return {reinterpret_cast<char*>(buf), static_cast<std::string::size_type>(sz)}; }
  void appendBufferToString(std::string& str) { if (buffer_ == nullptr) { return; } uint8_t* buf; uint32_t sz; getBuffer(&buf, &sz); str.append(reinterpret_cast<char*>(buf), sz); }
  void resetBuffer() { rBase_ = buffer_; rBound_ = buffer_; wBase_ = buffer_; if (!owner_) { wBound_ = wBase_; bufferSize_ = 0; } }
  void resetBuffer(uint8_t* buf, uint32_t sz, MemoryPolicy policy = OBSERVE) { TMemoryBuffer new_buffer(buf, sz, policy); this->swap(new_buffer); }
  void resetBuffer(uint32_t sz) { TMemoryBuffer new_buffer(sz); this->swap(new_buffer); }
  std::string readAsString(uint32_t len) { std::string str; (void)readAppendToString(str, len); return str; }
  uint32_t readAppendToString(std::string& str, uint32_t len);
  uint32_t readEnd() override { auto bytes = static_cast<uint32_t>(rBase_ - buffer_); if (rBase_ == wBase_) { resetBuffer(); } resetConsumedMessageSize(); return bytes; }
  uint32_t writeEnd() override { return static_cast<uint32_t>(wBase_ - buffer_); }
  uint32_t available_read() const { return static_cast<uint32_t>(wBase_ - rBase_); }
  uint32_t available_write() const { return static_cast<uint32_t>(wBound_ - wBase_); }
  uint8_t* getWritePtr(uint32_t len) { ensureCanWrite(len); return wBase_; }
  void wroteBytes(uint32_t len);
  uint32_t readAll(uint8_t* buf, uint32_t len) { return TBufferBase::readAll(buf, len); }
  uint32_t getBufferSize() const { return bufferSize_; }
  uint32_t getMaxBufferSize() const { return maxBufferSize_; }
  void setMaxBufferSize(uint32_t maxSize) { if (maxSize < bufferSize_) { throw TTransportException(TTransportException::BAD_ARGS,
                                "Maximum buffer size would be less than current buffer size"); } maxBufferSize_ = maxSize; }
protected:
  void swap(TMemoryBuffer& that) { using std::swap; swap(buffer_, that.buffer_); swap(bufferSize_, that.bufferSize_); swap(rBase_, that.rBase_); swap(rBound_, that.rBound_); swap(wBase_, that.wBase_); swap(wBound_, that.wBound_); swap(owner_, that.owner_); }
  void ensureCanWrite(uint32_t len);
  void computeRead(uint32_t len, uint8_t** out_start, uint32_t* out_give);
  uint32_t readSlow(uint8_t* buf, uint32_t len) override;
  void writeSlow(const uint8_t* buf, uint32_t len) override;
  const uint8_t* borrowSlow(uint8_t* buf, uint32_t* len) override;
  uint8_t* buffer_;
  uint32_t bufferSize_;
  uint32_t maxBufferSize_;
  bool owner_;
};

