// Create a minimal concrete TBase that consumes a struct from a protocol.
class __Fuzz_TBase_Reader : public apache::thrift::TBase {
public:
  uint32_t read(apache::thrift::protocol::TProtocol* iprot) override {
    using namespace apache::thrift::protocol;
    uint32_t xfer = 0;
    std::string s;
    try {
      TInputRecursionTracker tracker(*iprot);
      xfer += iprot->readStructBegin(s);
      while (true) {
        TType ftype; int16_t fid;
        xfer += iprot->readFieldBegin(s, ftype, fid);
        if (ftype == T_STOP) { break; }
        xfer += iprot->skip(ftype);
        xfer += iprot->readFieldEnd();
      }
      xfer += iprot->readStructEnd();
    } catch (...) {
      // Protocols may throw on malformed data; tolerate under fuzz.
    }
    return xfer;
  }
  uint32_t write(apache::thrift::protocol::TProtocol* oprot) const override {
    (void)oprot; return 0;
  }
};

