// Exercise multiple apache::thrift::to_string overloads/templates with bounded inputs
// Covers: int8_t, float, double, long double, vector<T>, set<T>, map<K,V>, vector<string>
{
  // Scalar specializations/overloads
  int8_t v8 = *FUZZ_PARAM(int8_t);
  float vf = *FUZZ_PARAM(float);
  double vd = *FUZZ_PARAM(double);
  long double vld = static_cast<long double>(*FUZZ_PARAM(double));

  // Invoke to_string on scalar overloads
  std::string s8  = apache::thrift::to_string(v8);
  std::string sf  = apache::thrift::to_string(vf);
  std::string sd  = apache::thrift::to_string(vd);
  std::string sld = apache::thrift::to_string(vld);

  // Container sizes (kept small for performance and recursion control)
  unsigned int nVec = (*FUZZ_PARAM(unsigned int) % 8);
  unsigned int nSet = (*FUZZ_PARAM(unsigned int) % 8);
  unsigned int nMap = (*FUZZ_PARAM(unsigned int) % 8);

  // Base random scalars for container population. Note: FUZZ_PARAM called in a loop
  // returns the same value; we derive variety by mixing with loop indices.
  int baseVec = *FUZZ_PARAM(int);
  int baseSet = *FUZZ_PARAM(int);
  int baseK   = *FUZZ_PARAM(int);
  int baseV   = *FUZZ_PARAM(int);

  // Build a vector<int>
  std::vector<int> vin;
  for (unsigned int i = 0; i < nVec; ++i) {
    vin.push_back(baseVec + static_cast<int>(i));
  }
  std::string svin = apache::thrift::to_string(vin);

  // Build a set<int>
  std::set<int> sin;
  for (unsigned int i = 0; i < nSet; ++i) {
    sin.insert(baseSet ^ static_cast<int>(i));
  }
  std::string ssin = apache::thrift::to_string(sin);

  // Build a map<int,int>
  std::map<int,int> min;
  for (unsigned int i = 0; i < nMap; ++i) {
    int k = baseK + static_cast<int>(i);
    int v = baseV - static_cast<int>(i);
    min[k] = v; // overwrites on duplicate keys; valid and exercises ordering
  }
  std::string smin = apache::thrift::to_string(min);

  // Also exercise vector<std::string>
  std::string fuzzStr = FUZZ_PARAM_STR();
  std::vector<std::string> vstr;
  unsigned int nStr = nVec % 5;
  for (unsigned int i = 0; i < nStr; ++i) {
    vstr.push_back(fuzzStr + ":" + std::to_string(i));
  }
  std::string svstr = apache::thrift::to_string(vstr);

  // Basic sanity checks on returned strings (non-null C-string view). Empty content is allowed.
  FUZZ_ASSERT(s8.c_str()  != nullptr, "int8_t to_string returned invalid string");
  FUZZ_ASSERT(sf.c_str()  != nullptr, "float to_string returned invalid string");
  FUZZ_ASSERT(sd.c_str()  != nullptr, "double to_string returned invalid string");
  FUZZ_ASSERT(sld.c_str() != nullptr, "long double to_string returned invalid string");
  FUZZ_ASSERT(svin.c_str()!= nullptr, "vector<int> to_string returned invalid string");
  FUZZ_ASSERT(ssin.c_str()!= nullptr, "set<int> to_string returned invalid string");
  FUZZ_ASSERT(smin.c_str()!= nullptr, "map<int,int> to_string returned invalid string");
  FUZZ_ASSERT(svstr.c_str()!= nullptr, "vector<string> to_string returned invalid string");

  // All data here is ephemeral; no persistent outputs.
}
