// Exercise apache::thrift::protocol::base64_encode with valid, non-overlapping buffers.
// Constraints enforced:
// - len in [1,3]
// - input has at least len bytes
// - output buffer size >= 4 and non-overlapping with input
// - No '=' padding or NUL termination expected; we only validate alphabet membership.
{
  using ::apache::thrift::protocol::base64_encode;

  // Generate source bytes; ensure we have at least 3 available (we will clamp len to [1,3]).
  std::string src = FUZZ_PARAM_STR();
  unsigned int len = (unsigned int)(*FUZZ_PARAM(unsigned int) % 3u) + 1u; // 1..3
  if (src.size() < len) { FUZZ_BAIL(); }

  // Prepare non-overlapping fixed-size input/output buffers.
  uint8_t inbuf[3] = {0,0,0};
  for (unsigned int i = 0; i < len; ++i) {
    inbuf[i] = static_cast<uint8_t>(src[i]);
  }
  uint8_t outbuf[4] = {0,0,0,0};

  // Call the target function.
  base64_encode(inbuf, (uint32_t)len, outbuf);

  // Validate: all 4 output bytes must be valid Base64 alphabet characters.
  auto is_b64 = [](uint8_t c) -> bool {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/';
  };
  if (!(is_b64(outbuf[0]) && is_b64(outbuf[1]) && is_b64(outbuf[2]) && is_b64(outbuf[3]))) {
    FUZZ_ASSERT(false, "base64_encode produced non-Base64 alphabet output");
  }

  // Validation summary: Input length and non-overlap satisfied; output alphabet checked.
}

// Exercise apache::thrift::protocol::base64_decode with in-place decoding.
// Constraints enforced:
// - len in [2,4]
// - buffer initially contains len valid Base64 chars with no '=' padding
// - operate in-place on a 4-byte buffer
// - property: re-encoding the decoded bytes reproduces the original len input chars
{
  using ::apache::thrift::protocol::base64_decode;
  using ::apache::thrift::protocol::base64_encode;

  // Choose input length in [2,4]
  uint32_t len = (uint32_t)(*FUZZ_PARAM(unsigned int) % 3u) + 2u; // 2..4

  // Build len Base64 characters from a random source string.
  static const char* alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  std::string rnd = FUZZ_PARAM_STR();
  if (rnd.size() < len) { FUZZ_BAIL(); }

  uint8_t buf[4] = {'A','A','A','A'}; // workspace for in-place decode
  uint8_t orig[4] = {0,0,0,0};         // keep a copy of original encoded input for roundtrip check
  for (uint32_t i = 0; i < len; ++i) {
    uint8_t idx = static_cast<uint8_t>(rnd[i]) & 63u; // 0..63
    buf[i] = static_cast<uint8_t>(alphabet[idx]);
    orig[i] = buf[i];
  }

  // Call the target function (in-place decode of first len bytes).
  base64_decode(buf, len);

  // Compute expected decoded length: 4->3, 3->2, 2->1
  uint32_t out_len = (len == 4 ? 3u : (len == 3 ? 2u : 1u));

  // Re-encode the decoded bytes and verify the first `len` characters match the original input.
  uint8_t reen[4] = {0,0,0,0};
  base64_encode(buf, out_len, reen);
  for (uint32_t i = 0; i < len; ++i) {
    if (reen[i] != orig[i]) {
      FUZZ_ASSERT(false, "base64 decode->encode roundtrip mismatch on prefix");
    }
  }

  // Validation summary: Constructed valid Base64 input, enforced len, and asserted roundtrip prefix equality.
}

