import json
import random
import struct
from typing import Any, Tuple

# This generator targets a Thrift TJSONProtocol reader consuming a struct.
# It should emit valid JSON texts representing Thrift messages/structs, with
# a variety of field types and nesting to exercise skip() and recursion tracking.
# Limit output to <= 4096 bytes.

MAX_BYTES = 4096

# A small set of interesting UTF-8 strings
INTERESTING_STRS = [
    "", "a", "hello", "Thrift", "\u0000nul", "\u2603 snowman", "\ud83d\ude03 smile",
    "multi-\nline", "quotes \" \"", "backslash \\",
]

# Generate a random UUID string in canonical form
def rand_uuid(r: random.Random) -> str:
    def rnd32():
        return r.getrandbits(32)
    a = rnd32()
    b = r.getrandbits(16)
    c = r.getrandbits(16)
    d = r.getrandbits(16)
    e1 = r.getrandbits(16)
    e2 = r.getrandbits(32)
    return f"{a:08x}-{b:04x}-{c:04x}-{d:04x}-{e1:04x}{e2:08x}"

def rand_number(r: random.Random) -> Any:
    choice = r.randrange(5)
    if choice == 0:
        return r.randint(-2**31, 2**31 - 1)
    if choice == 1:
        return r.randint(-2**63, 2**63 - 1)
    if choice == 2:
        # floating special-like values
        vals = [0.0, -0.0, 1.0, -1.0, 3.1415926535, 1e-300, 1e300]
        return r.choice(vals)
    if choice == 3:
        # boolean
        return bool(r.getrandbits(1))
    # large precise integer within JSON range
    return int(r.random() * 10**12) * (-1 if r.getrandbits(1) else 1)

def rand_string(r: random.Random) -> str:
    # sometimes pick from corpus
    if r.random() < 0.5:
        return r.choice(INTERESTING_STRS)
    # otherwise generate random unicode
    length = r.randint(0, 40)
    chars = []
    for _ in range(length):
        t = r.random()
        if t < 0.7:
            # basic ascii
            ch = r.randint(32, 126)
            chars.append(chr(ch))
        elif t < 0.9:
            # Latin-1 supplement
            ch = r.randint(0xA0, 0xFF)
            chars.append(chr(ch))
        else:
            # BMP random (avoid surrogates range for valid JSON encoding)
            ch = r.randint(0x20, 0xD7FF)
            chars.append(chr(ch))
    return "".join(chars)

def rand_binary_base64(r: random.Random) -> str:
    # Produce base64 as a JSON string; TJSONProtocol may base64-decode when expecting binary
    import base64
    n = r.randint(0, 64)
    data = bytes(r.getrandbits(8) for _ in range(n))
    return base64.b64encode(data).decode('ascii')

def rand_value(r: random.Random, depth: int) -> Any:
    # Generate a JSON value that corresponds to a Thrift type; keep depth bounded
    if depth <= 0:
        return r.choice([rand_string(r), rand_number(r), None, True, False])

    choice = r.randrange(8)
    if choice == 0:
        return rand_string(r)
    if choice == 1:
        return rand_number(r)
    if choice == 2:
        # list
        size = r.randint(0, 6)
        return [rand_value(r, depth - 1) for _ in range(size)]
    if choice == 3:
        # set represented as array (JSON has no set)
        size = r.randint(0, 6)
        arr = [rand_value(r, depth - 1) for _ in range(size)]
        return arr
    if choice == 4:
        # map with string keys
        size = r.randint(0, 6)
        obj = {}
        for _ in range(size):
            key_type = r.randrange(4)
            if key_type == 0:
                k = rand_string(r)
            elif key_type == 1:
                k = str(rand_number(r))
            elif key_type == 2:
                k = rand_uuid(r)
            else:
                k = json.dumps(rand_value(r, 0))
            obj[k] = rand_value(r, depth - 1)
        return obj
    if choice == 5:
        # binary as base64 inside a string
        return rand_binary_base64(r)
    if choice == 6:
        # uuid-ish string
        return rand_uuid(r)
    # nested object (struct)
    return rand_object(r, depth - 1)

def rand_field_name(r: random.Random) -> str:
    # Thrift structs in JSON use field names as strings; no strict schema here
    prefixes = ["id", "name", "value", "data", "list", "map", "set", "flag", "count", "uuid"]
    suffix = r.randint(0, 100)
    return f"{r.choice(prefixes)}_{suffix}"

def rand_object(r: random.Random, depth: int) -> dict:
    nfields = r.randint(0, 8)
    obj = {}
    for _ in range(nfields):
        # sometimes reuse same key to let later overwrite (valid JSON)
        key = rand_field_name(r)
        obj[key] = rand_value(r, depth)
    return obj

def build_message_like(r: random.Random) -> Any:
    # While the fuzzer calls readStructBegin directly, creating a JSON object
    # representing a typical Thrift message or struct header can still be useful.
    # We'll emit either:
    # - a plain object (struct)
    # - an array with mixed values
    # - a top-level scalar
    kind = r.random()
    if kind < 0.6:
        return rand_object(r, depth=3)
    elif kind < 0.85:
        return [rand_value(r, 3) for _ in range(r.randint(0, 6))]
    else:
        return rand_value(r, 3)

def to_json_bytes(obj: Any) -> bytes:
    # Use separators to keep size small; ensure ASCII-safe escapes
    s = json.dumps(obj, ensure_ascii=True, separators=(",", ":"))
    b = s.encode('utf-8')
    if len(b) > MAX_BYTES:
        # If too big, truncate by re-encoding a smaller repr
        # Fall back to a tiny empty object
        return b[:MAX_BYTES]
    return b

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    obj = build_message_like(r)

    # Occasionally wrap the struct into another layer to vary top-level
    wrap = r.random()
    if wrap < 0.2 and isinstance(obj, dict):
        # Emulate a message-like envelope sometimes used in JSON protocol
        envelope = {
            "method": rand_string(r) or "m",
            "type": r.choice([1, 2, 3, 4]),  # TMessageType values
            "seqid": r.randint(-10, 10),
            "args": obj,
        }
        obj = envelope
    elif wrap < 0.3:
        # Put struct inside an array
        obj = [obj]

    data = to_json_bytes(obj)
    # Ensure non-empty to drive parser; if empty, use minimal object
    if not data:
        data = b"{}"
    return data
